        test_scenario::return_shared(escrow);
        test_scenario::return_to_address(approver, approver_cap);
    };

    // Wait for unlock (advance epochs)
    test_scenario::next_epoch(&mut scenario, beneficiary);
    test_scenario::next_epoch(&mut scenario, beneficiary);
    test_scenario::next_epoch(&mut scenario, beneficiary);

    // Release
